import math
S={'aim':0.0,'mode':'rev','n':0}
def wrap(a):
    return (a+180.0)%360.0-180.0
def cl(x,a,b):
    return max(a,min(b,x))
def control(obs):
    try:
        return _c(obs)
    except Exception as e:
        print('err',e)
        return (0.0,-0.6,-23)

def _c(obs):
    S['n']+=1
    h=float(obs['hitch_deg'])
    rig=obs.get('rig') or {}
    scr=rig.get('screen_gaze_deg')
    look=scr if scr is not None else 180
    back=wrap(180.0-h)
    views=obs.get('views') or {}
    cam=views.get('camera')
    aim=None
    src=''
    if cam:
        pts=[]
        for p in cam.get('walls',[]):
            b,d=p[0],p[1]
            ph=math.radians(wrap(b-back))
            pts.append((d*math.cos(ph),d*math.sin(ph)))
        cs=[]
        for c in (cam.get('target_corners') or []):
            try:
                b,d=c[0],c[1]
            except Exception:
                continue
            ph=math.radians(wrap(b-back))
            cs.append((d*math.cos(ph),d*math.sin(ph)))
        if len(cs)>=2:
            cu=sum(c[0] for c in cs)/len(cs)
            cw=sum(c[1] for c in cs)/len(cs)
            aim=math.degrees(math.atan2(cw,max(cu,2.0)))
            src='bay'
        else:
            res=[]
            for pc in range(-60,61,3):
                r=math.radians(pc)
                c_,s_=math.cos(r),math.sin(r)
                free=7.0
                for (u,w) in pts:
                    al=u*c_+w*s_
                    pe=-u*s_+w*c_
                    if al>0 and abs(pe)<1.1:
                        free=min(free,al)
                res.append((pc,free))
            mx=max(f for _,f in res)
            runs=[];cur=[]
            for pc,f in res:
                if f>=mx-0.3:
                    cur.append(pc)
                else:
                    if cur: runs.append(cur)
                    cur=[]
            if cur: runs.append(cur)
            runs.sort(key=lambda r_:(-len(r_),abs(sum(r_)/len(r_))))
            a=sum(runs[0])/len(runs[0])
            L=None;R=None
            for (u,w) in pts:
                if -1.0<u<2.5 and abs(w)<4:
                    if w>0: L=w if L is None else min(L,w)
                    else: R=w if R is None else max(R,w)
            wc=0.0
            if L is not None and R is not None: wc=(L+R)/2
            elif L is not None: wc=min(0.0,L-1.6)
            elif R is not None: wc=max(0.0,R+1.6)
            aim=cl(a+10.0*wc,-45,45)
            src='gap %.0f wc %.2f mx %.1f'%(a,wc,mx)
    if aim is not None:
        S['aim']=0.7*S['aim']+0.3*aim
    else:
        S['aim']*=0.97
    st=obs.get('status')
    if st=='JACKKNIFED' or abs(h)>42:
        S['mode']='fwd'
    if S['mode']=='fwd':
        if abs(h)<8:
            S['mode']='rev'
        else:
            return (0.0,1.0,look)
    hd=cl(-0.9*S['aim'],-30,30)
    hr=math.radians(h)
    ff=math.degrees(math.atan(2.75*math.sin(hr)/(2.6+1.05*math.cos(hr))))
    steer=cl(ff+1.2*(h-hd),-34,34)
    if S['n']%10==0:
        print('t%.1f h%.1f hd%.1f aim%.1f st%.1f %s'%(obs['t'],h,hd,S['aim'],steer,src))
    return (steer,-0.9,look)

