import math
pts=[]
pose=[0.0,0.0,0.0]
last_t=None
mode='fwd'
fwd_dist=0.0
fwd_len=0.9
fwd_steer=20.0
seq=[-64,150,-64,64,-150,-64]
seq_i=0
seq_t=0.0
last_print=-10
last_touch=None
flip_t=-100
still_t=None

def clip(v,a,b):
    return max(a,min(b,v))

def control(obs):
    global last_t,mode,fwd_dist,fwd_len,fwd_steer,seq_i,seq_t,last_print,last_touch,flip_t,still_t
    t=obs['t']
    m=obs['motion']; v=m['v_mps']; st=obs['steer_deg']
    if last_t is not None:
        h=t-last_t
        x,y,yw=pose
        yw2=yw+v*math.tan(math.radians(st))/2.5*h
        x+=v*math.cos((yw+yw2)/2)*h; y+=v*math.sin((yw+yw2)/2)*h
        pose[0]=x; pose[1]=y; pose[2]=yw2
        if mode=='fwd': fwd_dist+=abs(v)*h
    last_t=t
    x,y,yw=pose; c=math.cos(yw); s=math.sin(yw)
    rig=obs['rig']
    vf=rig.get('vehicle_front',3.2)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    try: vf=float(vf)
    except Exception: vf=3.2
    hw=rig.get('vehicle_half_width',1.15) or 1.15
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]):
            b,d=w[0],w[1]
            px=ox+d*math.cos(math.radians(b)); py=oy+d*math.sin(math.radians(b))
            pts.append((x+c*px-s*py,y+s*px+c*py,t))
    keep=[p for p in pts if t-p[2]<3.0]
    pts[:]=keep[-2500:]
    loc=[]
    for wx,wy,tt in pts:
        dx=wx-x; dy=wy-y
        loc.append((c*dx+s*dy,-s*dx+c*dy))
    rx,ry=rig['trailer_rear']
    th=rig['trailer_heading_deg']
    thw=rig.get('trailer_half_width',1.2) or 1.2
    phi=obs['hitch_deg']
    fx=math.cos(math.radians(th)); fy=math.sin(math.radians(th))
    Lx=-fy; Ly=fx
    wL=None; wR=None; aL=None; aR=None
    fr=False; fl=False; frc=False; flc=False
    for px,py in loc:
        if 1.2<px<vf+0.3:
            if -(hw+0.25)<py<0: fr=True
            if 0<py<hw+0.25: fl=True
            if -(hw+0.07)<py<0: frc=True
            if 0<py<hw+0.07: flc=True
        dx=px-rx; dy=py-ry
        u=-(dx*fx+dy*fy); w=dx*Lx+dy*Ly
        if -4.4<u<1.0:
            if w>0: wL=w if wL is None else min(wL,w)
            else: wR=w if wR is None else max(wR,w)
        elif 1.0<=u<4.5:
            if w>0: aL=w if aL is None else min(aL,w)
            else: aR=w if aR is None else max(aR,w)
    dL=None if wL is None else wL-thw
    dR=None if wR is None else -wR-thw
    prog=(obs.get('progress') or {}).get('covered') or 0.0
    rem=(obs.get('progress') or {}).get('remaining')
    if aL is not None and aR is not None: mid=(aL+aR)/2
    elif aR is not None: mid=aR+2.0
    elif aL is not None: mid=aL-2.0
    else: mid=0.4 if prog<16 else 0.0
    alpha=math.degrees(math.atan2(mid,3.0))
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and (tg.get('dist_m') or 99)<10:
        ex,ey=rig['eye']
        tb=math.radians(tg['bearing_deg']); td=tg['dist_m']
        tx=ex+td*math.cos(tb)-rx; ty=ey+td*math.sin(tb)-ry
        u=-(tx*fx+ty*fy); w=tx*Lx+ty*Ly
        if u>0.5: alpha=0.5*alpha+0.5*math.degrees(math.atan2(w,u))
    status=obs.get('status')
    hold=m.get('hold_s') or 0
    touches=obs['counters']['touches']
    if last_touch is None: last_touch=touches
    def go_fwd(sd,ln):
        global mode,fwd_dist,fwd_len,fwd_steer,flip_t,still_t
        mode='fwd'; fwd_dist=0.0; fwd_len=ln; fwd_steer=sd; flip_t=t; still_t=None
    if touches>last_touch:
        last_touch=touches
        if mode=='rev':
            if (dR is not None and dR<0.3) or fr: go_fwd(20.0,1.0)
            elif (dL is not None and dL<0.3) or fl: go_fwd(-20.0,1.0)
            else: go_fwd(None,1.0)
        else:
            mode='rev'; flip_t=t
    if abs(v)<0.03 and hold<=0:
        if still_t is None: still_t=t
        elif t-still_t>4 and t-flip_t>5:
            if mode=='rev': go_fwd(None,1.0)
            else: mode='rev'; flip_t=t; still_t=None
    else: still_t=None
    if mode=='rev':
        if status=='JACKKNIFED' or abs(phi)>48:
            go_fwd(None,1.5)
        elif frc and not flc and v<-0.05: go_fwd(20.0,0.8)
        elif flc and not frc and v<-0.05: go_fwd(-20.0,0.8)
    if mode=='fwd' and fwd_dist>fwd_len:
        mode='rev'; flip_t=t
    if mode=='rev':
        phi_des=clip(1.3*alpha,-40,40)
        if dR is not None and dR<0.5: phi_des=max(phi_des,phi+(0.5-dR)*25)
        if dL is not None and dL<0.5: phi_des=min(phi_des,phi-(0.5-dL)*25)
        phi_des=clip(phi_des,-42,42)
        pr=math.radians(phi)
        ff=math.degrees(math.atan(2.5*math.sin(pr)/(3.6+1.3*math.cos(pr))))
        steer=clip(ff+2.5*(phi-phi_des),-45,45)
        if fr and not fl: steer=min(steer,-3)
        if fl and not fr: steer=max(steer,3)
        spd=-0.3
        if (dR is not None and dR<0.25) or (dL is not None and dL<0.25) or fr or fl: spd=-0.2
        if rem is not None and rem<4: spd=-0.22
    else:
        steer=fwd_steer if fwd_steer is not None else clip(-0.5*phi,-20,20)
        if fr: steer=max(steer,5)
        if fl: steer=min(steer,-5)
        spd=0.5
    if t-seq_t>0.7:
        seq_i=(seq_i+1)%len(seq); seq_t=t
    look=seq[seq_i]
    if t-last_print>4:
        last_print=t
        f2=lambda q:-9 if q is None else q
        print('t%.1f %s phi%.1f al%.1f mid%.2f dL%.2f dR%.2f st%.1f fr%d fl%d prog%.1f %s'%(t,mode,phi,alpha,mid,f2(dL),f2(dR),steer,fr,fl,prog,status))
    return (steer,spd,look)

