import math
L1=1.25;M=0.3;L2=0.85
X=0.0;Y=0.0;PSI=0.0
grid={}
Tm=None
mode='R';fx=0.0;fy=0.0;nf=0
last_touch=None;lastp=-10.0;prev=None;frz=None;t0=None;woke_end=False

def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def cl(v,a,b):
    return max(a,min(b,v))

def rigpts(x,y,th,phi,vf,hw,thw):
    c=math.cos(th);s=math.sin(th)
    out=[]
    for px,py in ((vf,hw),(vf,-hw),(vf-1.8,hw),(vf-1.8,-hw),(vf-0.9,hw),(vf-0.9,-hw)):
        out.append((x+c*px-s*py,y+s*px+c*py))
    hx=x-M*c;hy=y-M*s
    pt=th-math.radians(phi);ct=math.cos(pt);st=math.sin(pt)
    for a in (0.3,1.3):
        bx=hx-a*ct;by=hy-a*st
        out.append((bx-st*thw,by+ct*thw));out.append((bx+st*thw,by-ct*thw))
    return out

def clear(P,pts):
    m=81.0
    for (cx,cy) in P:
        for (qx,qy) in pts:
            d=(qx-cx)**2+(qy-cy)**2
            if d<m:m=d
    return math.sqrt(m)

def trear(x,y,th,phi):
    pt=th-math.radians(phi)
    return (x-M*math.cos(th)-1.3*math.cos(pt),y-M*math.sin(th)-1.3*math.sin(pt),pt+math.pi)

def sim(cmd,sgn,dist,x,y,th,phi,st,pts,vf,hw,thw,spd,thr):
    ds=0.15;n=max(1,int(round(dist/ds)))
    minc=9.0
    for i in range(n):
        if sgn<0:
            ff=math.degrees(math.atan(1.09*math.sin(math.radians(phi))))
            tg=cl(ff+2.0*(phi-cmd),-45,45)
        else:
            tg=cmd
        dm=48.0*ds/spd
        st+=cl(tg-st,-dm,dm)
        w=sgn*math.tan(math.radians(st))/L1
        ph=math.radians(phi)
        dpt=(sgn*math.sin(ph)-M*w*math.cos(ph))/L2*ds
        x+=sgn*math.cos(th)*ds;y+=sgn*math.sin(th)*ds;th+=w*ds
        phi=math.degrees(ph+w*ds-dpt)
        if abs(phi)>47: return None
        c=clear(rigpts(x,y,th,phi,vf,hw,thw),pts)
        if c<minc:minc=c
        if c<thr: return None
    return (x,y,th,phi,minc)

def control(obs):
    global X,Y,PSI,Tm,mode,fx,fy,nf,last_touch,lastp,prev,frz,t0,woke_end
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];st=obs['steer_deg']
    X+=v*math.cos(PSI)*dt;Y+=v*math.sin(PSI)*dt
    PSI+=v/L1*math.tan(math.radians(st))*dt
    c=math.cos(PSI);s=math.sin(PSI)
    phi=obs['hitch_deg'];t=obs['t'];status=obs.get('status')
    if t0 is None:t0=t
    rig=obs['rig']
    tc=obs['counters']['touches']
    if last_touch is None:last_touch=tc
    touched=tc>last_touch
    if touched:
        last_touch=tc;wake('touch #%d mode=%s phi=%.1f st=%.1f'%(tc,mode,phi,st))
    try:
        for k,vw in (obs.get('views') or {}).items():
            if not vw:continue
            o=vw['origin']
            for b,d in vw.get('walls',[]):
                if d<4.0:
                    br=math.radians(b);px=o[0]+d*math.cos(br);py=o[1]+d*math.sin(br)
                    wx=X+c*px-s*py;wy=Y+s*px+c*py
                    grid[(int(math.floor(wx/0.1)),int(math.floor(wy/0.1)))]=(wx,wy,t)
    except Exception as ex:
        print('view err',ex)
    for kk in [kk for kk,vv in grid.items() if t-vv[2]>8.0]:
        del grid[kk]
    pts=[(q[0],q[1]) for q in grid.values() if (q[0]-X)**2+(q[1]-Y)**2<10.9]
    try:
        tg=obs.get('target') or {}
        if tg.get('in_sight') and tg.get('bearing_deg') is not None:
            e0=rig['eye'];br=math.radians(tg['bearing_deg']);d=tg['dist_m']
            px=e0[0]+d*math.cos(br);py=e0[1]+d*math.sin(br)
            W=(X+c*px-s*py,Y+s*px+c*py)
            if Tm is None: Tm=[W[0],W[1]]
            else:
                g=0.05 if d>4 else 0.15
                Tm[0]+=g*(W[0]-Tm[0]);Tm[1]+=g*(W[1]-Tm[1])
    except Exception:
        pass
    cyc=(t-t0)%5.0
    gz=90 if cyc<3.2 else -140
    if t-t0<0.5:
        return (st,0.0,90)
    if Tm is None: Tm=[X-5*c,Y-5*s]
    vf=rig.get('vehicle_front',1.55)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    hw=rig.get('vehicle_half_width',0.525)
