    Pr=trear(X,Y,PSI,phi)
    dT=math.hypot(Tm[0]-Pr[0],Tm[1]-Pr[1])
    if frz is None and dT<2.0:
        frz=math.atan2(Tm[1]-Pr[1],Tm[0]-Pr[0])
    c0=clear(rigpts(X,Y,PSI,phi,vf,hw,thw),pts)
    thr=min(0.1,0.8*c0)
    def score(r,cmd):
        x,y,th,ph,mc=r
        px,py,bt=trear(x,y,th,ph)
        if frz is None:
            aim=math.atan2(Tm[1]-py,Tm[0]-px)
            sc=math.hypot(Tm[0]-px,Tm[1]-py)+0.8*abs(wrap(bt-aim))
        else:
