grid={}
Tm=None
mode='R';fx=0.0;fy=0.0;nf=0
last_touch=None;lastp=-10.0;prev=None;frz=None;t0=None;woke_end=False

def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def cl(v,a,b):
    return max(a,min(b,v))

def rigpts(x,y,th,phi,vf,hw,thw):
    c=math.cos(th);s=math.sin(th)
    out=[]
    for px,py in ((vf,hw),(vf,-hw),(vf-1.8,hw),(vf-1.8,-hw),(vf-0.9,hw),(vf-0.9,-hw)):
        out.append((x+c*px-s*py,y+s*px+c*py))
    hx=x-M*c;hy=y-M*s
    pt=th-math.radians(phi);ct=math.cos(pt);st=math.sin(pt)
    for a in (0.3,1.3):
        bx=hx-a*ct;by=hy-a*st
        out.append((bx-st*thw,by+ct*thw));out.append((bx+st*thw,by-ct*thw))
    return out

def clear(P,pts):
    m=81.0
    for (cx,cy) in P:
        for (qx,qy) in pts:
            d=(qx-cx)**2+(qy-cy)**2
            if d<m:m=d
    return math.sqrt(m)

def trear(x,y,th,phi):
    pt=th-math.radians(phi)
    return (x-M*math.cos(th)-1.3*math.cos(pt),y-M*math.sin(th)-1.3*math.sin(pt),pt+math.pi)

def sim(cmd,sgn,dist,x,y,th,phi,st,pts,vf,hw,thw,spd,thr):
    ds=0.15;n=max(1,int(round(dist/ds)))
    minc=9.0
