    wait_ok = abs(sd-s)<2 and hold<=0
    if not wait_ok:
        st['t0']=t
    if t-st['t0']>=du:
        st['i']+=1;st['t0']=t
        if st['i']>=len(SEQ):
            st['done']=True;wake('sequence done, tot %.2f'%st['tot'])
            return (0.0,0.0,0)
    s,sp,du=SEQ[st['i']]
